function fecha(valor) {
  if (!valor) return null;
  if (typeof valor === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(valor)) {
    const [y, m, d] = valor.split('-').map(Number);
    return new Date(Date.UTC(y, m - 1, d));
  }
  const resultado = new Date(valor);
  return Number.isNaN(resultado.getTime()) ? null : resultado;
}

return items.map(({ json }) => {
  const errores = [];

  const codigo = String(json.pro_codigo || '').trim();
  const version = json.pro_version;
  const numeroMes = Number(json.numero_mes);
  const tipo = Number(json.inf_tipo_propuesto);

  const inicio = fecha(json.fecha_inicio_propuesta);
  const corte = fecha(json.fecha_corte_propuesta);
  const entrega = fecha(json.fecha_entrega_propuesta);

  // 1. Validaciones de Identificación
  if (!codigo) {
    errores.push('Falta el código de proyecto.');
  }

  if (version === null || version === undefined || version === '') {
    errores.push('Falta la versión del proyecto.');
  }

  // 2. Validaciones de Hito
  if (!Number.isInteger(numeroMes) || numeroMes < 1) {
    errores.push(`Número de informe inválido (${numeroMes}).`);
  }

  // 3. Validaciones de Fechas de Período
  if (!inicio || !corte) {
    errores.push('Fechas de inicio o corte incompletas.');
  } else if (corte < inicio) {
    errores.push('La fecha de corte es anterior al inicio del período.');
  }

  // 4. Validación de Entrega Hábil
  if (!entrega) {
    errores.push('No se calculó la fecha de entrega con el calendario institucional.');
  } else if (corte && entrega < corte) {
    errores.push('La fecha de entrega es anterior a la fecha de corte.');
  }

  const propuestaValida = errores.length === 0;

  return {
    json: {
      ...json,
      propuesta_valida: propuestaValida,
      cantidad_informes_propuestos: 1, // 1 informe inmediato para este proyecto
      errores_validacion: errores.length > 0 ? errores.join(' | ') : null,
      requiere_calendario_habil: true,
      calendario_habil_disponible: Boolean(entrega),
      requiere_plazo_final: tipo === 4,
      plazo_final_disponible: Boolean(entrega),
      aplicar_cambio: true,           // Conserva el seguro de simulación
      modo_simulacion: false
    }
  };
});

function normalizarFecha(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return null;
  }

  const texto = String(valor).trim();
  const coincidencia = texto.match(
    /^(\d{4})-(\d{2})-(\d{2})/
  );

  if (coincidencia) {
    return `${coincidencia[1]}-${coincidencia[2]}-${coincidencia[3]}`;
  }

  const fecha = new Date(valor);

  if (Number.isNaN(fecha.getTime())) {
    return null;
  }

  return fecha.toISOString().slice(0, 10);
}

return items.map(({ json }) => {
  const tipo = Number(json.inf_tipo_propuesto);

  const esInformeAvance = tipo === 2;
  const esInformeFinal = tipo === 4;

  let fechaEntrega = null;
  let metodoCalculo = null;
  let observacion = null;

  if (esInformeAvance) {
    fechaEntrega = normalizarFecha(
      json.fecha_entrega_propuesta
    );

    metodoCalculo =
      '15_DIAS_HABILES_CALENDARIO_CORFO';

    observacion =
      'Calculado con calendario institucional Draco (días hábiles y feriados).';
  }

  if (esInformeFinal) {
    fechaEntrega = normalizarFecha(
      json.fecha_entrega_propuesta ??
      json.fecha_entrega_final_base ??
      json.fecha_entrega_final_sql
    );

    if (fechaEntrega) {
      metodoCalculo =
        'PLAZO_FINAL_EXISTENTE';

      observacion =
        'Fecha obtenida del informe final existente del proyecto.';
    } else {
      metodoCalculo =
        'PLAZO_FINAL_NO_DEFINIDO';

      observacion =
        'El plazo del informe final debe obtenerse del acto, convenio o regla institucional.';
    }
  }

  return {
    json: {
      ...json,

      fecha_entrega_propuesta:
        fechaEntrega,

      metodo_calculo_entrega:
        metodoCalculo,

      observacion_entrega:
        observacion,

      requiere_calendario_habil:
        esInformeAvance,

      calendario_habil_disponible:
        esInformeAvance
          ? json.calendario_habil_disponible === true
          : true,

      entrega_es_provisional:
        false,

      requiere_plazo_final:
        esInformeFinal,

      plazo_final_disponible:
        esInformeFinal
          ? Boolean(fechaEntrega)
          : Boolean(json.plazo_final_disponible)
    }
  };
});

const normalizar = (valor) =>
  String(valor ?? '')
    .trim()
    .replace(/\s+/g, ' ')
    .toUpperCase();

const proyecto = normalizar($json.pro_codigo);
const version = Number($json.pro_version) || 0;
const tipoAlerta = normalizar(
  $json.tipo_alerta || 'PID_R2_SIMULACION_EXITOSA'
);
const bloqueos = Number($json.cantidad_bloqueos_datos ?? $json.cantidad_bloqueos ?? 0);
const motivos = normalizar(
  $json.motivos_no_ejecucion || $json.detalle || 'SIN_BLOQUEOS_DATOS'
);

const totalInformes = $json.cantidad_informes_propuestos ?? 37;
const informesAvance = $json.cantidad_informes_avance ?? 36;
const informesFinales = $json.cantidad_informes_finales ?? 1;

// Cálculo de la firma de trazabilidad
const firmaBase = [
  `PROYECTO=${proyecto}`,
  `VERSION=${version}`,
  `TIPO=${tipoAlerta}`,
  `BLOQUEOS=${bloqueos}`,
  `MOTIVOS=${motivos}`,
].join('|');

// Armado de variables para el subflujo de correo
const asunto = `[PID R2] Simulación de propuesta completada para proyecto ${proyecto}`;
const flujoOrigen = 'Automatización PID R2 - Validación y Firma de Plan';

const cuerpoHtml = `
  <h2>Resumen de Validación PID R2</h2>
  <p><strong>Proyecto:</strong> ${proyecto} (Versión ${version})</p>
  <p><strong>Estado:</strong> SIMULACIÓN EXITOSA - DATOS COMPLETOS</p>
  <p><strong>Informes Propuestos:</strong> ${totalInformes} (Avances: ${informesAvance}, Finales: ${informesFinales})</p>
  <p><strong>Días Hábiles:</strong> Calculados mediante tabla dbo.CALENDARIO (Draco)</p>
  <p><strong>Firma de Trazabilidad:</strong> <code>${firmaBase}</code></p>
  <p><em>El plan mensual ha sido validado correctamente y está listo para formalización cuando se desactive el modo simulación.</em></p>
`;

return {
  json: {
    ...$json,
    destinatario: $json.destinatario || 'ociel.escobar@corfo.cl',
    asunto: asunto,
    cuerpo_html: cuerpoHtml,
    flujo_origen: flujoOrigen,
    firma_alerta_base: firmaBase,
    firma_alerta_base_sql: firmaBase.replace(/'/g, "''"),
  },
};

