return items.map(({ json }) => {
  const totalExistentes = Number(json.total_informes_existentes ?? 0);
  const colisionesMismoNumero = Number(json.colisiones_mismo_numero ?? 0);
  const crearPlanAutorizable = json.crear_plan_completo_autorizable === true;

  // Si no tiene informes y está autorizado -> CREAR_PLAN
  // Si ya tiene informes previos pero no colisiona -> CONFIGURAR_PLAN_MENSUAL
  const accionSegura = (totalExistentes === 0 && crearPlanAutorizable)
    ? 'CREAR_PLAN'
    : 'CONFIGURAR_PLAN_MENSUAL';

  return {
    json: {
      ...json, // Conserva todos los campos necesarios para la inserción (fechas, tipo, etc.)
      total_informes_existentes: totalExistentes,
      informes_finales_existentes: Number(json.informes_finales_existentes ?? 0),
      cantidad_colisiones: colisionesMismoNumero,
      crear_plan_completo_autorizable: crearPlanAutorizable,
      accion_pid_segura: accionSegura,
      diagnostico_colision: json.diagnostico_colision,
      requiere_configuracion_plan: accionSegura === 'CONFIGURAR_PLAN_MENSUAL',
      puede_insertar_plan_completo: accionSegura === 'CREAR_PLAN' && colisionesMismoNumero === 0,

      // Control de producción/simulación
      modo_simulacion: false,
      aplicar_cambio: true
    }
  };
});

function fechaISO(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return null;
  }

  const texto = String(valor).trim();

  // Si ya viene como YYYY-MM-DD o como fecha ISO.
  const coincidenciaISO = texto.match(
    /^(\d{4})-(\d{2})-(\d{2})/
  );

  if (coincidenciaISO) {
    return (
      `${coincidenciaISO[1]}-` +
      `${coincidenciaISO[2]}-` +
      `${coincidenciaISO[3]}`
    );
  }

  // Respaldo por si n8n lo convirtió en un objeto Date
  // o en otro formato reconocible por JavaScript.
  const fecha = new Date(valor);

  if (Number.isNaN(fecha.getTime())) {
    return null;
  }

  const anio = fecha.getUTCFullYear();

  const mes = String(
    fecha.getUTCMonth() + 1
  ).padStart(2, '0');

  const dia = String(
    fecha.getUTCDate()
  ).padStart(2, '0');

  return `${anio}-${mes}-${dia}`;
}

function booleano(valor) {
  return (
    valor === true ||
    valor === 1 ||
    String(valor).trim().toLowerCase() === 'true'
  );
}

return items.map(item => {
  const entrada = item.json;

  const fechaInicioSQL = fechaISO(
    entrada.fecha_inicio_base
  );

  const fechaTerminoSQL = fechaISO(
    entrada.fecha_termino_base
  );

  const fechaEntregaFinalSQL = fechaISO(
    entrada.fecha_entrega_final_base
  );

  const plazoFinalDisponible =
    booleano(entrada.plazo_final_disponible) &&
    fechaEntregaFinalSQL !== null;

  return {
    json: {
      ...entrada,

      proyecto_sql: String(
        entrada.pro_codigo ?? ''
      ).trim(),

      version_sql: String(
        entrada.pro_version ?? ''
      ).trim(),

      fecha_inicio_sql:
        fechaInicioSQL,

      fecha_termino_sql:
        fechaTerminoSQL,

      numero_informe_final_existente:
        entrada.numero_informe_final_existente ?? null,

      fecha_corte_final_sql:
        fechaISO(
          entrada.fecha_corte_final_existente
        ),

      fecha_entrega_final_sql:
        fechaEntregaFinalSQL,

      plazo_final_disponible:
        plazoFinalDisponible
    }
  };
});

return items.map(({ json }) => {
  const bloqueos = [];

  if (!json.propuesta_valida) {
    bloqueos.push(json.errores_validacion || 'Propuesta no válida');
  }
  if (json.modo_simulacion === true) {
    bloqueos.push('Modo simulación activo (escritura bloqueada por seguridad)');
  }
  if (json.aplicar_cambio !== true) {
    bloqueos.push('Flag aplicar_cambio en false');
  }

  return {
    json: {
      pro_codigo: json.pro_codigo,
      pro_version: json.pro_version,
      pro_codigo_humano: json.pro_codigo_humano,
      resultado_ejecucion: 'SIMULADO_NO_APLICADO',
      propuesta_valida: json.propuesta_valida,
      numero_mes_propuesto: json.numero_mes,
      fecha_corte_propuesta: json.fecha_corte_propuesta,
      fecha_entrega_propuesta: json.fecha_entrega_propuesta,
      tipo_periodo_propuesto: json.tipo_periodo_propuesto,
      modo_simulacion: json.modo_simulacion,
      aplicar_cambio: json.aplicar_cambio,
      cantidad_bloqueos: bloqueos.length,
      motivos_no_ejecucion: bloqueos.join(' | '),
      fecha_simulacion: new Date().toISOString()
    }
  };
});

const item = $input.first().json;

const fechaTermino = item.fecha_termino ? new Date(item.fecha_termino) : null;
const ultimaFechaCorte = item.ultima_fecha_corte ? new Date(item.ultima_fecha_corte) : null;
const ultimoNumero = item.ultimo_inf_numero || 0;

// Si ya igualó o superó la fecha de término, el plan está finalizado
if (!fechaTermino || (ultimaFechaCorte && ultimaFechaCorte >= fechaTermino)) {
  return [{
    json: {
      ...item,
      plan_finalizado: true,
      motivo: "El proyecto ya alcanzó o superó su fecha oficial de término."
    }
  }];
}

// Proyectar siguiente mes (+1 mes calendario)
let siguienteCorte = new Date(ultimaFechaCorte);
siguienteCorte.setMonth(siguienteCorte.getMonth() + 1);

// Si sobrepasa el término oficial, se acota a la fecha término
if (siguienteCorte > fechaTermino) {
  siguienteCorte = fechaTermino;
}

// Fecha de entrega sugerida (ej. 15 días posteriores al corte)
const siguienteEntrega = new Date(siguienteCorte);
siguienteEntrega.setDate(siguienteEntrega.getDate() + 15);

return [{
  json: {
    ...item,
    plan_finalizado: false,
    siguiente_inf_numero: ultimoNumero + 1,
    siguiente_fecha_corte: siguienteCorte.toISOString().slice(0, 10),
    siguiente_fecha_entrega: siguienteEntrega.toISOString().slice(0, 10),
    nombre_informe: `Informe de Avance N° ${ultimoNumero + 1}`
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.completos = (staticData.completos || 0) + 1;

return [{
  json: {
    pro_codigo: $json.pro_codigo,
    estado: 'PLAN_COMPLETO',
    mensaje: $json.motivo || 'El plan mensual ya cubrió la vigencia total del proyecto.'
  }
}];

